#include <MoltenVK/mvk_private_api.h>
#include <stdio.h>
int main(void) {
 MVKConfiguration config = {0}; size_t size = sizeof(config);
 VkResult result = vkGetMoltenVKConfigurationMVK(VK_NULL_HANDLE, &config, &size);
 printf("{\"result\":%d,\"header_version\":\"%s\",\"size\":%zu,\"synchronousQueueSubmits\":%u,\"useMetalArgumentBuffers\":%u,\"prefillMetalCommandBuffers\":%u}\n",result,MVK_VERSION_STRING,size,config.synchronousQueueSubmits,config.useMetalArgumentBuffers,config.prefillMetalCommandBuffers);
 return result == VK_SUCCESS ? 0 : 1;
}
